def divide_text(a_text, b_text):
    try:
        a = float(a_text)
        b = float(b_text)
        result = a / b
    except ValueError:
        return False, "숫자 형식 오류"
    except ZeroDivisionError:
        return False, "0으로 나눌 수 없음"
    return True, result

